"""Read-only audit of the exact archived phase. No threshold or historical score edits."""
import gzip,json,csv
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation
D=Path(__file__).parent;source=D/'evidence/legacy_centered_hold5_01/physics.jsonl.gz';out=D/'evidence/consistency_20261014/stability';out.mkdir(parents=True,exist_ok=False)
rows=[json.loads(x) for x in gzip.open(source,'rt')];rows=[r for r in rows if r['phase']=='right_independent_hold']
assert len(rows)==1250 and all(r['arms']['left']['actual_pad_gap_m']>.07 for r in rows)
t=np.array([r['sim_time_s'] for r in rows]);p=np.array([r['object_pose'][:3] for r in rows]);v=np.array([r['object_velocity'] for r in rows]);q=np.array([r['object_pose'][3:] for r in rows]);rot=Rotation.from_quat(np.roll(q,-1,axis=1));fd=np.diff(p,axis=0)/np.diff(t)[:,None]
tcp=np.array([r['arms']['right']['actual_grasp_center_world'] for r in rows]);fr=np.array([r['arms']['right']['flange_pose_world'][3:] for r in rows]);rrot=Rotation.from_quat(np.roll(fr,-1,axis=1));relp=rrot.inv().apply(p-tcp);relrot=rrot.inv()*rot;dr=relp-relp[0];ang=(relrot[0].inv()*relrot).magnitude()
contacts=[]
for r in rows:
 cs=[c for c in r['contacts'] if 'target_cube' in c['names']];left=any(any(x.startswith('L__') for x in c['names']) for c in cs);table=any('table' in c['names'] for c in cs);depth=max([0]+[-x['separation'] for c in cs for x in c['points'] if any('Support_Link' in n for n in c['names'])]);contacts.append((r['bilateral_contact']['right'],left,table,depth))
def stats(a):return {k:float(x) for k,x in zip(['min','median','mean','p95','max'],[np.min(a),np.median(a),np.mean(a),np.percentile(a,95),np.max(a)])}
summary={'source':str(source.relative_to(D)),'phase':'right_independent_hold','start_step':rows[0]['step'],'end_step':rows[-1]['step'],'samples':len(rows),'duration_recorded_s':len(rows)*.004,'between_first_last_s':float(t[-1]-t[0]),'dt_range_s':[float(np.diff(t).min()),float(np.diff(t).max())],'same_reference_point':'Actor origin in old log; COM offset is checked independently in runtime_info.json. Cube is centered box. No smoothing or records filtered inside this phase. FD uses adjacent post-step positions.','reported_world_speed_m_s':stats(np.linalg.norm(v,axis=1)),'world_position_difference_speed_m_s':stats(np.linalg.norm(fd,axis=1)),'world_position_range_m':np.ptp(p,axis=0).tolist(),'observed_net_displacement_m':(p[-1]-p[0]).tolist(),'integrated_reported_velocity_over_matching_intervals_m':(v[1:]*np.diff(t)[:,None]).sum(axis=0).tolist(),'relative_position_range_m':np.ptp(relp,axis=0).tolist(),'maximum_relative_position_drift_m':float(np.linalg.norm(dr,axis=1).max()),'maximum_relative_rotation_drift_degrees':float(np.rad2deg(ang).max()),'right_bilateral_fraction':float(np.mean([c[0] for c in contacts])),'left_contact_samples':sum(c[1] for c in contacts),'table_contact_samples':sum(c[2] for c in contacts),'maximum_pad_penetration_m':max(c[3] for c in contacts),'original_speed_criterion_m_s':.03,'original_speed_criterion_all_samples_pass':bool(np.all(np.linalg.norm(v,axis=1)<.03)),'old_score_unchanged':True,'conclusion':'Reported velocity fails the old criterion but does not demonstrate sustained sliding: pose differences and relative grip pose show retention. Solver velocity and integrated transform motion are distinct quantities. No new PASS replaces the historical score.'}
(out/'summary.json').write_text(json.dumps(summary,indent=2))
with (out/'exact_phase.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['step','time_s','engine_speed_m_s','adjacent_fd_speed_m_s','relative_drift_m','relative_rotation_degrees','right_bilateral','left_contact','table_contact','pad_penetration_m'])
 for i,r in enumerate(rows):w.writerow([r['step'],t[i],np.linalg.norm(v[i]),'' if i==0 else np.linalg.norm(fd[i-1]),np.linalg.norm(dr[i]),np.rad2deg(ang[i]),*contacts[i]])
import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
fig,axs=plt.subplots(3,1,figsize=(10,8),sharex=True);axs[0].plot(t,np.linalg.norm(v,axis=1)*1000,label='PhysX reported COM speed');axs[0].plot(t[1:],np.linalg.norm(fd,axis=1)*1000,label='adjacent pose difference speed');axs[0].axhline(30,c='red',ls='--',label='unchanged old speed limit');axs[0].set_ylabel('mm/s');axs[0].legend();axs[1].plot(t,np.linalg.norm(dr,axis=1)*1000);axs[1].set_ylabel('relative position drift (mm)');axs[2].plot(t,np.rad2deg(ang));axs[2].set_ylabel('relative rotation drift (deg)');axs[2].set_xlabel('simulation seconds');fig.tight_layout();fig.savefig(out/'phase_audit.png');plt.close(fig);print(json.dumps(summary,indent=2))
